Your expense tracker is below. Add an amount, pick a category and the total and category bars update as you go. Entries stay on this page only, so they're gone when you close it.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><style>
body{font-family:Segoe UI,Arial,sans-serif;margin:0;padding:16px;background:#f6f6f8;color:#222}
h2{margin:0 0 12px}
.card{background:#fff;border-radius:10px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px #0002}
.row{display:flex;gap:8px;flex-wrap:wrap}
input,select,button{padding:8px;border:1px solid #ccc;border-radius:6px;font-size:14px}
button{background:#2b6cb0;color:#fff;border:0;cursor:pointer}
button.x{background:#c53030;padding:4px 8px}
.total{font-size:26px;font-weight:600}
.bar{height:10px;background:#2b6cb0;border-radius:5px}
.cat{margin:6px 0}
.item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee}
.muted{color:#666;font-size:13px}
</style></head><body>
<h2>Monthly expenses</h2>
<div class="card">
<div class="row">
<input id="d" type="date" style="flex:1">
<select id="c">
<option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option><option>Shopping</option><option>Health</option><option>Fun</option><option>Other</option>
</select>
<input id="n" placeholder="Note" style="flex:2">
<input id="a" type="number" min="0" placeholder="Amount (₹)" style="flex:1">
<button id="add">Add</button>
</div>
</div>
<div class="card">
<div class="row" style="align-items:center;justify-content:space-between">
<div><div class="muted">Total this month</div><div class="total" id="t">₹0</div></div>
<div><label class="muted">Month </label><input id="m" type="month"></div>
</div>
<div id="cats"></div>
</div>
<div class="card"><div id="list"></div></div>
<script>
var items=[],id=0;
var $=function(x){return document.getElementById(x)};
var today=new Date().toISOString().slice(0,10);
$('d').value=today;$('m').value=today.slice(0,7);
function inr(v){return '₹'+Number(v).toLocaleString('en-IN')}
function esc(s){return s.replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
function render(){
var mo=$('m').value;
var cur=items.filter(function(i){return i.d.slice(0,7)===mo}).sort(function(a,b){return a.d<b.d?1:-1});
var tot=cur.reduce(function(s,i){return s+i.a},0);
$('t').textContent=inr(tot);
var by={};cur.forEach(function(i){by[i.c]=(by[i.c]||0)+i.a});
var h='';
Object.keys(by).sort(function(a,b){return by[b]-by[a]}).forEach(function(k){
var p=tot?by[k]/tot*100:0;
h+='<div class="cat"><div class="row" style="justify-content:space-between"><span>'+k+'</span><span>'+inr(by[k])+' ('+Math.round(p)+'%)</span></div><div class="bar" style="width:'+p+'%"></div></div>';
});
$('cats').innerHTML=h;
$('list').innerHTML=cur.length?cur.map(function(i){
return '<div class="item"><div>'+esc(i.n||i.c)+'<div class="muted">'+i.d+' · '+i.c+'</div></div><div>'+inr(i.a)+' <button class="x" data-id="'+i.id+'">✕</button></div></div>';
}).join(''):'<div class="muted">No expenses for this month yet.</div>';
}
$('add').onclick=function(){
var a=parseFloat($('a').value);
if(!a||a<=0||!$('d').value)return;
items.push({id:++id,d:$('d').value,c:$('c').value,n:$('n').value.trim(),a:a});
$('m').value=$('d').value.slice(0,7);
$('a').value='';$('n').value='';
render();
};
$('list').onclick=function(e){
var k=e.target.getAttribute('data-id');
if(k){items=items.filter(function(i){return i.id!=k});render();}
};
$('m').onchange=render;
render();
</script>
</body></html>
```

Here's your water tracker with a goal of 8 glasses. Tap **+** after each glass, **−** to undo, and it resets each new day.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: system-ui, sans-serif; text-align: center; padding: 24px; background: #f0f8ff; color: #123; }
  h1 { font-size: 22px; margin-bottom: 4px; }
  #count { font-size: 48px; font-weight: 700; margin: 12px 0 4px; }
  #msg { min-height: 22px; margin-bottom: 14px; }
  #glasses { display: flex; justify-content: center; gap: 8px; flex-wrap: wrap; margin-bottom: 18px; }
  .g { width: 34px; height: 48px; border: 2px solid #3a8dde; border-radius: 4px 4px 10px 10px; background: #fff; }
  .g.full { background: #6cb8f5; }
  button { font-size: 22px; width: 56px; height: 56px; border-radius: 50%; border: 0; background: #3a8dde; color: #fff; margin: 0 8px; cursor: pointer; }
  button.small { font-size: 14px; width: auto; height: auto; padding: 8px 14px; border-radius: 8px; background: #888; margin-top: 18px; }
</style>
</head>
<body>
  <h1>Water today</h1>
  <div id="count">0 / 8</div>
  <div id="msg"></div>
  <div id="glasses"></div>
  <button id="minus">−</button>
  <button id="plus">+</button><br>
  <button class="small" id="reset">Reset today</button>
<script>
  var GOAL = 8;
  var key = "water-" + new Date().toISOString().slice(0, 10);
  var n = 0;
  try { n = parseInt(localStorage.getItem(key), 10) || 0; } catch (e) {}
  function save() { try { localStorage.setItem(key, String(n)); } catch (e) {} }
  function draw() {
    document.getElementById("count").textContent = n + " / " + GOAL;
    var box = document.getElementById("glasses");
    box.innerHTML = "";
    for (var i = 0; i < GOAL; i++) {
      var d = document.createElement("div");
      d.className = "g" + (i < n ? " full" : "");
      box.appendChild(d);
    }
    var m = document.getElementById("msg");
    if (n >= GOAL) m.textContent = "Goal reached. Well done!";
    else m.textContent = (GOAL - n) + " more to go";
  }
  document.getElementById("plus").onclick = function () { n++; save(); draw(); };
  document.getElementById("minus").onclick = function () { if (n > 0) n--; save(); draw(); };
  document.getElementById("reset").onclick = function () { n = 0; save(); draw(); };
  draw();
</script>
</body>
</html>
```
